function inside(point: Point, ring: readonly Point[]): boolean {
  let result = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const a = ring[i], b = ring[j];
    if ((a[1] > point[1]) !== (b[1] > point[1]) &&
        point[0] < (b[0] - a[0]) * (point[1] - a[1]) / (b[1] - a[1]) + a[0]) result = !result;
  }
  return result;
}
function segmentDistance(p: Point, a: Point, b: Point): number {
  const dx = b[0] - a[0], dz = b[1] - a[1];
  const t = Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dz) / (dx * dx + dz * dz || 1)));
  return Math.hypot(p[0] - a[0] - t * dx, p[1] - a[1] - t * dz);
}
export function museumLandscapeClearance(x: number, z: number): number {
  let clearance = Infinity;
  for (const way of CLEARANCE_WAYS) for (let i = 1; i < way.points.length; i++)
    clearance = Math.min(clearance, segmentDistance([x, z], way.points[i - 1], way.points[i]) - way.width / 2);
  return clearance;
}

/** Adds mapped northern lawns and planted details; the existing campus owns southern lawn surfaces. */
export function buildMuseumLandscape(groundAt: Ground): THREE.Group {
  const root = new THREE.Group(); root.name = 'museum-landscape';
  const lawn = new THREE.MeshLambertMaterial({ color: 0x657c45, side: THREE.DoubleSide });
  const leaves = new THREE.MeshLambertMaterial({ color: 0x405f31 });
  const lightLeaves = new THREE.MeshLambertMaterial({ color: 0x718146 });
  const trunk = new THREE.MeshLambertMaterial({ color: 0x66533f });
  const hedge = new THREE.MeshLambertMaterial({ color: 0x456039 });
  const paving = new THREE.MeshLambertMaterial({ color: 0xc7c4b4, side: THREE.DoubleSide });
  const batches = new Map<THREE.Material, THREE.BufferGeometry[]>();
  function add(geometry: THREE.BufferGeometry, material: THREE.Material) {
    const flat = geometry.index ? geometry.toNonIndexed() : geometry;
    if (flat !== geometry) geometry.dispose();
    flat.deleteAttribute('uv'); const batch = batches.get(material) ?? []; batch.push(flat); batches.set(material, batch);
  }
  const treeSites: { x: number; z: number; base: number; source: number; radius: number }[] = [];
  const lawnPositions: number[] = [];
  // New surfaces exclude existing campus lawns and all buffered road/path footprints.
  function emitTriangle(a: Point, b: Point, c: Point, depth = 0) {
    // Subdivision conforms to the bluff slope rather than stretching one plane over the grade.
    const length = Math.max(Math.hypot(a[0] - b[0], a[1] - b[1]), Math.hypot(b[0] - c[0], b[1] - c[1]), Math.hypot(c[0] - a[0], c[1] - a[1]));
    if (length > 3 && depth < 9) {
      const ab: Point = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2], bc: Point = [(b[0] + c[0]) / 2, (b[1] + c[1]) / 2], ca: Point = [(c[0] + a[0]) / 2, (c[1] + a[1]) / 2];
      emitTriangle(a, ab, ca, depth + 1); emitTriangle(ab, b, bc, depth + 1); emitTriangle(ca, bc, c, depth + 1); emitTriangle(ab, bc, ca, depth + 1); return;
    }
    for (const p of [a, c, b]) lawnPositions.push(p[0], groundAt(...p) + .14, p[1]);
  }
  for (const [a, b, c] of NORTHERN_LAWN_TRIANGLES) emitTriangle(a, b, c);
  for (const area of MUSEUM_LANDSCAPE_AREAS) {
    const xs = area.points.map(p => p[0]), zs = area.points.map(p => p[1]);
    const spacing = area.kind === 'wood' ? 6.8 : 24;
    for (let z = Math.min(...zs) + 4; z < Math.max(...zs) - 2; z += spacing) {
      for (let x = Math.min(...xs) + 3; x < Math.max(...xs) - 2; x += spacing) {
        const jitter = Math.sin(x * .69 + z * .53);
        const p: Point = [x + jitter * 2, z + Math.cos(x * .37) * 1.5];
        const radius = area.kind === 'wood' ? 2.6 + (jitter + 1) * .6 : 2.3;
        if (!inside(p, area.points) || p[1] > -622 || p[1] < -1030 || museumLandscapeClearance(...p) < radius + .7) continue;
        if (treeSites.some(t => Math.hypot(t.x - p[0], t.z - p[1]) < (t.radius + radius) * .78)) continue;
        if (CAMPUS_CONTEXT.trees.some(t => Math.hypot(Number(t[0]) - p[0], Number(t[1]) - p[1]) < 5)) continue;
        const base = groundAt(...p), height = area.kind === 'wood' ? 8 + (jitter + 1) * 1.7 : 6.7;
        treeSites.push({ x: p[0], z: p[1], base, source: area.id, radius });
        const stem = new THREE.CylinderGeometry(.22, .34, height * .68, 5); stem.translate(p[0], base + height * .34, p[1]); add(stem, trunk);
        const crown = new THREE.IcosahedronGeometry(radius, 1); crown.scale(1, 1.18, 1); crown.translate(p[0], base + height * .76, p[1]); add(crown, jitter > .3 ? lightLeaves : leaves);
      }
    }
  }
  if (lawnPositions.length) {
    const geometry = new THREE.BufferGeometry(); geometry.setAttribute('position', new THREE.Float32BufferAttribute(lawnPositions, 3)); geometry.computeVertexNormals(); add(geometry, lawn);
  }
  // Four mapped transverse paths divide the five Cudahy lawns. Hedges sit inside the adjacent lawn,
  // with a central opening for the water channel; 3m height follows MAM's stated ten-foot hedges.
  const dividers: readonly (readonly [Point, Point])[] = [
    [[564.3, -448.8], [598.0, -451.0]], [[566.4, -419.6], [600.2, -421.8]],
    [[568.5, -390.3], [602.3, -392.5]], [[570.6, -361.0], [604.4, -363.2]],
  ];
  const groundPatches = CAMPUS_CONTEXT.grass.filter(t => !t.raised);
  const hedgeSites: Point[] = [];
  for (const [a, b] of dividers) {
    const dx = b[0] - a[0], dz = b[1] - a[1], length = Math.hypot(dx, dz), n = Math.ceil(length / 1.5);
    const nx = -dz / length, nz = dx / length;
    const positions: number[] = [];
    for (let i = 0; i < n; i++) {
      const t0 = i / n, t1 = (i + 1) / n;
      const p: Point = [a[0] + dx * t0, a[1] + dz * t0], q: Point = [a[0] + dx * t1, a[1] + dz * t1];
      const corners = [[p[0] - nx, p[1] - nz], [p[0] + nx, p[1] + nz], [q[0] - nx, q[1] - nz], [q[0] + nx, q[1] + nz]];
      for (const index of [0, 1, 2, 2, 1, 3]) { const c = corners[index]; positions.push(c[0], groundAt(c[0], c[1]) + .22, c[1]); }
      const t = (t0 + t1) / 2; if (Math.abs(t - .5) < .06) continue;
      const center: Point = [a[0] + dx * t + nx * 2.1, a[1] + dz * t + nz * 2.1];
      if (!groundPatches.some(patch => inside(center, patch.points.map(([x, z]): Point => [x, z])))) continue;
      const h = new THREE.BoxGeometry(length / n + .04, 3, .85); h.rotateY(-Math.atan2(dz, dx)); h.translate(center[0], groundAt(...center) + 1.5, center[1]); add(h, hedge); hedgeSites.push(center);
    }
    const geometry = new THREE.BufferGeometry(); geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3)); geometry.computeVertexNormals(); add(geometry, paving);
  }
  for (const [material, parts] of batches) {
    const geometry = mergeGeometries(parts); if (!geometry) throw new Error('Museum landscape batch failed'); parts.forEach(p => p.dispose());
    const mesh = new THREE.Mesh(geometry, material);
    mesh.name = material === lawn ? 'museum-northern-lawns' : material === paving ? 'museum-garden-paths' : material === hedge ? 'museum-garden-hedges' : material === trunk ? 'museum-tree-trunks' : 'museum-tree-canopies';
    mesh.receiveShadow = true; mesh.castShadow = material !== lawn && material !== paving; root.add(mesh);
  }
  root.userData.treeSites = treeSites; root.userData.hedgeSites = hedgeSites;
  root.userData.source = 'Cached OSM ground grass/wood polygons; MAM Cudahy Gardens description; supplied Google Earth references';
  root.userData.estimated = 'Tree size, density and hedge thickness are interpreted, not surveyed.';
  return root;
}
